/**
 * McLeod TMS REST API Types
 * Based on McLeod REST API documentation
 *
 * IMPORTANT: McLeod uses REST (NOT SOAP). All endpoints are under /ws/api
 */

/**
 * McLeod RowCustomer structure as returned by GET /customers/new
 * Only set fields that exist in the actual response - do not invent fields
 */
export interface RowCustomer {
  // Primary identifier - auto-generated by McLeod or set by us
  id?: string;

  // Company information
  name: string;                    // Legal company name (required)
  name2?: string;                  // DBA / alternate name
  address1: string;                // Street address (required)
  address2?: string;               // Street address line 2
  city: string;                    // City (required)
  state: string;                   // 2-letter state code (required)
  zip_code: string;                // Postal code (required)
  country_code?: string;           // Country code (default: USA)

  // Contact information
  phone1?: string;                 // Primary phone
  phone2?: string;                 // Secondary phone
  fax?: string;                    // Fax number
  email?: string;                  // Primary email

  // Tax/regulatory
  federal_id?: string;             // EIN/Tax ID (9 digits)
  ic_number?: string;              // Interstate Commerce (MC) number

  // Status and classification
  status?: string;                 // Customer status (A=Active, I=Inactive)
  customer_type?: string;          // Customer type/category

  // Credit
  credit_limit?: number;           // Credit limit in dollars
  credit_status?: string;          // Credit status code

  // Payment
  terms?: string;                  // Payment terms code

  // Assignment
  salesperson_id?: string;         // Salesperson code

  // Primary contact fields (embedded in customer)
  contact_name?: string;           // Primary contact name

  // Audit fields
  entered_user_id?: string;        // User who created
  entered_date?: string;           // Date created

  // Allow additional fields from McLeod that we don't explicitly type
  [key: string]: unknown;
}

/**
 * McLeod RowContact structure for ContactService
 * RowType must be "C" for customer contacts
 */
export interface RowContact {
  // Required fields
  id?: string;                     // Contact ID (auto-generated)
  row_type: 'C';                   // C = Customer contact
  parent_row_id: string;           // Customer ID

  // Contact info
  first_name?: string;
  last_name?: string;
  name?: string;                   // Full name if not split
  email?: string;
  phone?: string;
  phone2?: string;
  fax?: string;

  // Classification
  contact_type_id?: string;        // Contact type (LOGISTICS, AP, PRIMARY, etc.)
  is_primary?: boolean;            // Primary contact flag

  // Allow additional fields
  [key: string]: unknown;
}

/**
 * McLeod RowComment structure for CommentService
 */
export interface RowComment {
  id?: string;
  row_type: 'C';                   // C = Customer comment
  parent_row_id: string;           // Customer ID
  comment_type?: string;           // Comment type code
  comment: string;                 // Comment text
  entered_user_id?: string;        // User who entered
  entered_date?: string;           // Date entered

  [key: string]: unknown;
}

/**
 * Customer search parameters for GET /customers/search
 * Use prefixes like customer.* or no prefix per docs
 */
export interface CustomerSearchParams {
  'customer.federal_id'?: string;
  'customer.name'?: string;
  'customer.city'?: string;
  'customer.state'?: string;
  'customer.zip_code'?: string;
  'customer.id'?: string;
  // Allow string params for query building
  [key: string]: string | undefined;
}

/**
 * Search results wrapper
 */
export interface CustomerSearchResult {
  customers: RowCustomer[];
  totalCount: number;
  hasMore: boolean;
}

/**
 * Token response from POST /users/login
 */
export interface LoginResponse {
  token: string;
  expiresIn?: number;
}

